out = []
for ko, en, say, more, wk in T:
    for s in (ko, en, say, more):
        assert not any(c in s for c in "—–·"), s
    out.append({"ko": ko, "en": en, "say": say, "more": more, "week": wk})
keys = [(x["en"] or x["ko"]).lower() for x in out]
assert len(keys) == len(set(keys)), [k for k in keys if keys.count(k) > 1]
p = os.path.join(os.path.dirname(os.path.abspath(__file__)), "용어사전.json")
with open(p, "w", encoding="utf-8", newline="\n") as f:
    json.dump(out, f, ensure_ascii=False, indent=1)
print(len(out), "terms")
